#!/usr/bin/env python3
"""Generate the SPIR-V instruction builder methods of nxb-xlate (`impl CodeGenContext`) from Spv.Generator/Autogenerated.

usage: gen_spirv_builder.py <Spv.Generator dir> <CodeGen/Spirv dir> <out dir>
Only the methods whose C# name occurs in the Spirv code generator sources are generated (output split in files < 600 lines).
"""
import re, sys, os

spv, spirv_src, out = sys.argv[1:4]
used = set()
for f in os.listdir(spirv_src):
    if f.endswith('.cs'):
        used |= set(re.findall(r'[A-Za-z_][A-Za-z0-9_]*', open(os.path.join(spirv_src, f)).read()))

KEYWORDS = {'type', 'match', 'ref', 'mod', 'loop', 'move', 'use', 'in', 'fn', 'let', 'box', 'impl', 'as', 'where', 'static', 'return', 'break', 'continue', 'true', 'false', 'self', 'super', 'crate', 'do', 'yield', 'try', 'final', 'typeof', 'macro', 'override', 'virtual', 'abstract', 'become', 'priv', 'unsized', 'dyn', 'async', 'await', 'const', 'else', 'enum', 'extern', 'for', 'if', 'pub', 'struct', 'trait', 'unsafe', 'while'}

def snake(n):
    s = re.sub(r'(?<=[a-z0-9])(?=[A-Z])', '_', n)
    s = re.sub(r'(?<=[A-Z])(?=[A-Z][a-z])', '_', s)
    s = s.lower()
    return s + '_' if s in KEYWORDS else s

core = open(os.path.join(spv, 'Autogenerated/CoreGrammar.cs')).read()
glsl = open(os.path.join(spv, 'Autogenerated/GlslStd450Grammar.cs')).read()

methods = {}  # name -> (params, body, ispan)
for m in re.finditer(r'public Instruction (\w+)\(((?:[^()]|\([^()]*\))*)\)\s*\{(.*?)\n        \}', core, re.S):
    name, params, body = m.group(1), m.group(2), m.group(3)
    if name not in used or name in ('Source', 'SourceExtension', 'String'):
        continue
    has_span = 'params ReadOnlySpan' in params
    if name in methods and not has_span:
        continue
    if name in methods and not methods[name][2] and not has_span:
        continue
    methods[name] = (params, body, has_span)

def parse_params(p):
    res = []
    if not p.strip():
        return res
    for part in re.split(r',\s*(?![^<]*>)', p):
        part = part.strip()
        span = part.startswith('params ReadOnlySpan<')
        mm = re.match(r'(?:params )?(ReadOnlySpan<(\w+)>|[\w]+) (\w+)(?: = (.+))?$', part)
        ty = mm.group(2) if mm.group(2) else mm.group(1)
        res.append((ty, mm.group(3), span, mm.group(4)))
    return res

def rust_ty(ty, span, default):
    if span:
        return {'Instruction': '&[Inst]', 'IOperand': '&[Operand]', 'LiteralInteger': '&[Lit]'}[ty]
    if ty == 'Instruction':
        return 'Option<Inst>' if default == 'null' else 'Inst'
    if ty == 'LiteralInteger':
        return 'Lit'
    if ty == 'string':
        return '&str'
    if ty == 'bool':
        return 'bool'
    return 'Option<u32>' if default else 'u32'   # enums

def operand_expr(ty, name, span, default, cond_param=None):
    n = snake(name)
    if span:
        if ty == 'Instruction':
            return f'self.m.add_all(i, {n}.iter().map(|&x| Operand::Ref(x)));'
        if ty == 'IOperand':
            return f'self.m.add_all(i, {n}.iter().cloned());'
        return f'self.m.add_all(i, {n}.iter().map(|&x| Operand::Lit(x)));'
    if ty == 'Instruction':
        return f'self.m.add(i, Operand::Ref({n}));'
    if ty == 'LiteralInteger':
        return f'self.m.add(i, Operand::Lit({n}));'
    if ty == 'string':
        return f'self.m.add(i, Operand::Str({n}.to_string()));'
    if default:
        return f'self.m.add(i, Operand::Lit(Lit::I32({n}.unwrap_or_default() as i32)));'
    return f'self.m.add(i, Operand::Lit(Lit::I32({n} as i32)));'

def gen_method(name, params, body):
    ps = parse_params(params)
    pmap = {p[1]: p for p in ps}
    sig = ', '.join(f'{snake(n)}: {rust_ty(t, s, d)}' for t, n, s, d in ps)
    lines = []
    nm = re.search(r'NewInstruction\(Op\.(\w+)(?:, (GetNewId\(\)|Instruction\.InvalidId))?(?:, (\w+))?\)', body)
    op, idexpr, rt = nm.group(1), nm.group(2), nm.group(3)
    rt_expr = f'Some({snake(rt)})' if rt else 'None'
    if idexpr and 'GetNewId' in idexpr:
        lines.append(f'let i = self.m.new_with_id(op::{op} as u16, {rt_expr});')
    else:
        lines.append(f'let i = self.m.new_instruction(op::{op} as u16, {rt_expr});')
    # operand statements, with conditions
    stmts = re.findall(r'(if \((\w+) (?:!= \([\w]+\)int\.MaxValue|!= null)\)\s*\{\s*result\.AddOperand\((\w+)\);\s*\}|result\.AddOperand\((\w+)\);)', body)
    for full, cond, inner, plain in stmts:
        if plain:
            t, n, s, d = pmap[plain]
            if d == 'null':
                lines.append(f'if let Some(x) = {snake(n)} {{ self.m.add(i, Operand::Ref(x)); }}')
            else:
                lines.append(operand_expr(t, n, s, d))
        else:
            ct, cn, cs, cd = pmap[cond]
            t, n, s, d = pmap[inner]
            if not cd:
                lines.append(operand_expr(t, n, s, d))
            elif n == cn and d == 'null':
                lines.append(f'if let Some(x) = {snake(n)} {{ self.m.add(i, Operand::Ref(x)); }}')
            elif n == cn:
                lines.append(f'if {snake(cn)}.is_some() {{ {operand_expr(t, n, s, d)} }}')
            else:
                lines.append(f'if {snake(cn)}.is_some() {{ {operand_expr(t, n, s, None)} }}')
    if 'AddToFunctionDefinitions(result)' in body:
        lines.append('self.m.add_to_function_definitions(i);')
        ret = 'i'
    elif 'AddAnnotation(result)' in body:
        lines.append('self.m.add_annotation(i);'); ret = 'i'
    elif 'AddDebug(result)' in body:
        lines.append('self.m.add_debug(i);'); ret = 'i'
    elif 'AddTypeDeclaration(result, forceIdAllocation)' in body:
        ret = 'self.m.add_type(i, force_id_allocation)'
    elif 'AddConstant(result)' in body:
        ret = 'self.m.add_constant(i)'
    else:
        ret = 'i'
    lines.append(ret)
    return f'    pub fn {snake(name)}(&mut self, {sig}) -> Inst {{ ' + ' '.join(lines) + ' }'

funcs = [gen_method(n, *methods[n][:2]) for n in sorted(methods, key=lambda n: core.index(f'public Instruction {n}('))]

gl = []
for m in re.finditer(r'public Instruction (Glsl\w+)\(Instruction resultType((?:, Instruction \w+)*)\)\s*\{\s*return ExtInst\(resultType, AddExtInstImport\("GLSL.std.450"\), (\d+)(?:, [^)]*)?\);', glsl):
    name, args, num = m.group(1), m.group(2), m.group(3)
    if name not in used:
        continue
    names = re.findall(r'Instruction (\w+)', args)
    sig = ''.join(f', {snake(a)}: Inst' for a in names)
    lst = ', '.join(snake(a) for a in names)
    gl.append(f'    pub fn {snake(name)}(&mut self, result_type: Inst{sig}) -> Inst {{ let set = self.m.add_ext_inst_import("GLSL.std.450"); self.ext_inst(result_type, set, {num}, &[{lst}]) }}')

hdr = '//! Produced by tools/gen_spirv_builder.py from Spv.Generator/Autogenerated: do not edit.\n#![allow(clippy::too_many_arguments, clippy::let_and_return)]\n\nuse super::context::CodeGenContext;\nuse super::spirv_op::op;\nuse crate::spv::{Inst, Lit, Operand};\n\n#[rustfmt::skip]\nimpl CodeGenContext {\n'
allf = funcs + gl
per = 380
for k in range(0, len(allf), per):
    with open(os.path.join(out, f'spirv_build_{k // per}.rs'), 'w') as f:
        f.write(hdr + '\n'.join(allf[k:k + per]) + '\n}\n')
print(len(funcs), 'core methods,', len(gl), 'glsl methods', file=sys.stderr)
